namespace Finance.Core;
public record InstrumentInput(string Kind,string Number,int Day,long Principal,long? Bank=null,long? Employee=null,string Lender="",string Type="",int? MaturityDay=null,decimal Rate=0,long MaturityAmount=0,long EMI=0,int? RecoveryDay=null,int Installments=0,string Remarks="",bool OpeningBalance=false);
public record BGInput(string Number,int Day,long Bank,string Branch,string Beneficiary,long Amount,string Type,string Purpose,int ExpiryDay,int ClaimDay,string Dispatch="",int? DeliveredDay=null,bool Confirmed=false,string Remarks="");
public partial class Engine
{
    public long CreateInstrument(InstrumentInput x)=>Write(d=>CreateInstrument(d,x));
    long CreateInstrument(Db d,InstrumentInput x){
        Value.Require(x.Kind is "FD" or "Employee Loan" or "Business Loan","Select the instrument type.");Value.Require(!string.IsNullOrWhiteSpace(x.Number)&&x.Principal>0,"Enter the account/deposit number and a positive principal.");Value.Require(x.Rate>=0&&x.EMI>=0&&x.Installments>=0,"Interest, EMI and installments cannot be negative.");Unlocked(d,x.Day);
        if(x.Kind=="FD")Value.Require(x.MaturityDay>=x.Day,"FD maturity cannot precede its creation.");
        if(x.Kind=="Employee Loan"){Active(d,"Employee",x.Employee);Value.Require(x.RecoveryDay>=x.Day,"Recovery start cannot precede the loan date.");}
        if(x.Kind!="Business Loan"&&!x.OpeningBalance)Active(d,"Bank",x.Bank);
        long id=d.Insert("Instrument",new Dictionary<string,object?>{["Kind"]=x.Kind,["Number"]=x.Number.Trim(),["Day"]=x.Day,["Principal"]=x.Principal,["BankId"]=x.Bank,["EmployeeId"]=x.Employee,["Lender"]=x.Lender,["Type"]=x.Type,["MaturityDay"]=x.MaturityDay,["Rate"]=x.Rate.ToString(System.Globalization.CultureInfo.InvariantCulture),["MaturityAmount"]=x.MaturityAmount,["EMI"]=x.EMI,["RecoveryDay"]=x.RecoveryDay,["Installments"]=x.Installments,["Remarks"]=x.Remarks});
        if(x.Kind!="Business Loan")Post(d,x.Kind,x.Day,x.Number,[new(x.Kind=="FD"?"FD":"ELOAN",x.Principal,Employee:x.Employee,Instrument:id),x.OpeningBalance?new("OPEN",-x.Principal):new("BANK",-x.Principal,Bank:x.Bank)]);
        Audit(d,"Instrument",id,"Created",null,x);return id;
    }
    void CloseFD(Db d,long id,int day,long bank,long interest){var fd=d.Row("SELECT * FROM Instrument WHERE Id=@p0 AND Kind='FD'",id);Value.Require(Value.Text(fd["Status"])=="Active","FD is not active.");Value.Require(day>=Value.Long(fd["Day"]),"Closure cannot precede creation.");Value.Require(interest>=0,"Interest cannot be negative.");Value.Require(Value.Text(fd["Type"])!="Other Lien","Release the other lien before closing this FD.");Value.Require(d.N("SELECT COUNT(*) FROM BGFD WHERE FDId=@p0 AND ReleasedDay IS NULL",id)==0,"Release the FD lien before closing or renewing it.");Active(d,"Bank",bank);long principal=Balance(d,"FD",instrument:id);Value.Require(principal>0,"FD has no remaining principal.");Post(d,"FD Closure",day,Value.Text(fd["Number"]),[new("FD",-principal,Instrument:id),new("BANK",principal+interest,Bank:bank),new("INTERESTIN",-interest,Instrument:id)]);d.Exec("UPDATE Instrument SET Status='Closed',ClosureDay=@p0 WHERE Id=@p1",day,id);Audit(d,"Instrument",id,"Closed",null,new{day,interest});}
    public void CloseFD(long id,int day,long bank,long interest)=>Write(d=>{CloseFD(d,id,day,bank,interest);return 0;});
    public long RenewFD(long oldId,int day,long bank,long interest,InstrumentInput replacement)=>Write(d=>{Value.Require(replacement.Kind=="FD"&&replacement.Day==day&&replacement.Bank==bank,"Renewal must use the same settlement date and bank.");CloseFD(d,oldId,day,bank,interest);long id=CreateInstrument(d,replacement);d.Exec("UPDATE Instrument SET Status='Renewed' WHERE Id=@p0",oldId);Audit(d,"Instrument",oldId,"Renewed",null,new{Replacement=id});return id;});
    public long SaveBG(BGInput x,long? id=null)=>Write(d=>{
        Unlocked(d,x.Day);Value.Require(!string.IsNullOrWhiteSpace(x.Number)&&!string.IsNullOrWhiteSpace(x.Beneficiary)&&x.Amount>0,"Enter BG number, beneficiary and a positive amount.");Value.Require(x.ExpiryDay>=x.Day&&x.ClaimDay>=x.ExpiryDay,"Check the BG expiry and claim dates.");Value.Require(x.DeliveredDay==null||x.DeliveredDay>=x.Day,"Delivery cannot precede the BG date.");Active(d,"Bank",x.Bank);
        var v=new Dictionary<string,object?>{["Number"]=x.Number,["Day"]=x.Day,["BankId"]=x.Bank,["Branch"]=x.Branch,["Beneficiary"]=x.Beneficiary,["Amount"]=x.Amount,["Type"]=x.Type,["Purpose"]=x.Purpose,["ExpiryDay"]=x.ExpiryDay,["ClaimDay"]=x.ClaimDay,["Dispatch"]=x.Dispatch,["DeliveredDay"]=x.DeliveredDay,["Confirmed"]=x.Confirmed?1:0,["Remarks"]=x.Remarks};
        object? old=null;if(id==null)id=d.Insert("BG",v);else {var r=d.Row("SELECT * FROM BG WHERE Id=@p0",id);Unlocked(d,(int)Value.Long(r["Day"]));Value.Require(Value.Text(r["Status"])=="Active","Closed guarantees cannot be amended.");old=r.ItemArray;d.Exec($"UPDATE BG SET {string.Join(',',v.Keys.Select((k,i)=>k+"=@p"+i))} WHERE Id=@p{v.Count}",v.Values.Append<object?>(id).ToArray());}Audit(d,"BG",id,old==null?"Created":"Amended",old,x);return id.Value;
    });
    public void LinkFD(long bg,long fd,int day)=>Write(d=>{Unlocked(d,day);var b=d.Row("SELECT * FROM BG WHERE Id=@p0",bg);var f=d.Row("SELECT * FROM Instrument WHERE Id=@p0",fd);Value.Require(Value.Text(b["Status"])=="Active"&&Value.Text(f["Kind"])=="FD"&&Value.Text(f["Status"])=="Active","Select an active BG and active FD.");Value.Require(Value.Text(f["Type"])!="Other Lien","Release the existing other lien before linking this FD.");Value.Require(day>=Math.Max(Value.Long(b["Day"]),Value.Long(f["Day"])),"Lien date cannot precede the BG or FD.");d.Exec("INSERT INTO BGFD(BGId,FDId,LinkedDay) VALUES(@p0,@p1,@p2)",bg,fd,day);Audit(d,"BG",bg,"FD linked",null,new{fd,day});return 0;});
    public void ReleaseFD(long fd,int day,string reason)=>Write(d=>{Unlocked(d,day);Value.Require(!string.IsNullOrWhiteSpace(reason),"Enter the lien release reference.");var instrument=d.Row("SELECT * FROM Instrument WHERE Id=@p0 AND Kind='FD'",fd);if(Value.Text(instrument["Type"])=="Other Lien"){Value.Require(day>=Value.Long(instrument["Day"]),"Release cannot precede FD date.");d.Exec("UPDATE Instrument SET Type='Free FD' WHERE Id=@p0",fd);Audit(d,"Instrument",fd,"Other lien released",null,new{day},reason);return 0;}var link=d.Row("SELECT * FROM BGFD WHERE FDId=@p0 AND ReleasedDay IS NULL",fd);Value.Require(day>=Value.Long(link["LinkedDay"]),"Release date cannot precede lien date.");d.Exec("UPDATE BGFD SET ReleasedDay=@p0 WHERE Id=@p1",day,link["Id"]);Audit(d,"BG",Value.Long(link["BGId"]),"Lien released",null,new{fd,day},reason);return 0;});
    public void CloseBG(long id,int day,string reason)=>Write(d=>{Unlocked(d,day);Value.Require(!string.IsNullOrWhiteSpace(reason),"Enter a closure reason/reference.");var r=d.Row("SELECT * FROM BG WHERE Id=@p0",id);Value.Require(Value.Text(r["Status"])=="Active"&&day>=Value.Long(r["Day"]),"Check the BG status and closure date.");d.Exec("UPDATE BG SET Status='Closed',ClosureDay=@p0 WHERE Id=@p1",day,id);Audit(d,"BG",id,"Closed",null,new{day},reason);return 0;});
    public void CloseLoan(long id,int day,string reason)=>Write(d=>{Unlocked(d,day);var r=d.Row("SELECT * FROM Instrument WHERE Id=@p0",id);string kind=Value.Text(r["Kind"]);Value.Require(kind is "Employee Loan" or "Business Loan","Select a loan.");Value.Require(day>=Value.Long(r["Day"])&&Balance(d,kind=="Employee Loan"?"ELOAN":"BLOAN",instrument:id)==0,"Only a fully settled loan can be closed.");Value.Require(!string.IsNullOrWhiteSpace(reason),"Enter the closure reference.");d.Exec("UPDATE Instrument SET Status='Closed',ClosureDay=@p0 WHERE Id=@p1",day,id);Audit(d,"Instrument",id,"Closed",null,null,reason);return 0;});

    public void LoanTerms(long id,decimal rate,long emi,int nextDay,string reason)=>Write(d=>{
        Unlocked(d,nextDay);var r=d.Row("SELECT * FROM Instrument WHERE Id=@p0",id);
        Value.Require(Value.Text(r["Kind"]) is "Business Loan" or "Employee Loan","Select a loan.");
        Value.Require(Value.Text(r["Status"])=="Active"&&rate>=0&&rate<=100&&emi>=0&&nextDay>=Value.Long(r["Day"]),"Check the loan terms and next recovery date.");
        Value.Require(!string.IsNullOrWhiteSpace(reason),"A change reason is required.");d.Exec("UPDATE Instrument SET Rate=@p0,EMI=@p1,RecoveryDay=@p2 WHERE Id=@p3",rate.ToString(System.Globalization.CultureInfo.InvariantCulture),emi,nextDay,id);Audit(d,"Instrument",id,"Loan terms changed",r.ItemArray,new{rate,emi,nextDay},reason);return 0;
    });
}
